"""joint fraction number
    Args:
        text_list (list): text list.

    Returns:
        (list): processed text list.
    """
def joint_number(text_list: Any) -> object {
    new_list = [];
    i = 0;
    while (i < len(text_list)) {
        if (
            (text_list[i] == '(')
            and ((i + 4) < len(text_list))
            and (text_list[(i + 4)] == ')')
        ) {
            sub = ''.join(text_list[i:(i + 5)]);
            new_list.append(sub);
            i = i + 5;
        } else {
            new_list.append(text_list[i]);
            i += 1;
        }
    }
    return new_list;
}
